/// <summary>
/// The <c>AVAProcessGuidePageCls_Extension</c> represents a extension of ProcessGuidePage class.
/// </summary>
/// <remarks>
/// AVA_8065_10657_MDEAutoPackContainerType
/// </remarks>
[
    ExtensionOf(classStr(ProcessGuidePage))
]
final class AVAProcessGuidePageCls_Extension
{
}

Method.Source:
/// <summary>
/// update a textbox control on the page.
/// </summary>
/// <param name = "_name">
/// The name of the control.
/// </param>
/// <param name = "_labelText">
/// The label text of the control.
/// </param>
/// <param name = "_extendedTypeId">
/// <c>extendedTypeId</c> of the text data in the textbox.
/// </param>
/// <param name = "_enabled">
/// A <c>Boolean</c> value indicating whether the control is enabled.
/// </param>
/// <param name = "_textValue">
/// The text data of the control.
/// </param>
/// <remarks>
/// AVA_8065_10657_MDEAutoPackContainerType
/// </remarks>
public void avaUpdateTextBox(ProcessGuidePageControlName    _name,
                             str                            _labelText,
                             extendedTypeId                 _extendedTypeId, 
                             boolean                        _enabled = true,
                             str                            _textValue = '')
{
    ListEnumerator          avaListEnumerator;
    Object                  avaControl;
    ProcessGuidePageTextBox avaTextBox;

    if (this.controlsList)
    {
        avaListEnumerator = this.controlsList.getEnumerator();

        while (avaListEnumerator.moveNext())
        {
            avaControl = avaListEnumerator.current();

            if (avaControl is ProcessGuidePageTextBox)
            {
                avaTextBox = avaControl;

                if (avaTextBox.parmName() == _name
                 && avaTextBox.parmData() != _textValue)
                {
                    avaTextBox.avaParmData(_textValue);
                }
            }
        }
    }
}
